package com.ksh321.songrecord.api.storage;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import static org.assertj.core.api.Assertions.*;

class R2ExperimentSettingsTests {
 private MockEnvironment settings(){var e=new MockEnvironment();e.setActiveProfiles("staging");return e.withProperty("songrecord.deployment.storage-scope","experiment").withProperty("songrecord.deployment.environment","staging").withProperty("DB_NAME","song_record_experiment").withProperty("DB_USER","song_record_experiment").withProperty("songrecord.storage.environment","dev").withProperty("songrecord.storage.role","api").withProperty("songrecord.storage.dev.account-id","a".repeat(32)).withProperty("songrecord.storage.dev.temporary-bucket","song-record-experiment-temporary").withProperty("songrecord.storage.dev.final-bucket","song-record-experiment-final").withProperty("songrecord.storage.dev.api.access-key","api-access").withProperty("songrecord.storage.dev.api.secret-key","api-secret").withProperty("songrecord.storage.dev.playback.access-key","reader-access").withProperty("songrecord.storage.dev.playback.secret-key","reader-secret");}
 @Test void writerAndDedicatedReaderAcceptOnlyExplicitExperimentPair(){var e=settings();assertThat(R2Settings.from(e).temporaryBucket).isEqualTo("song-record-experiment-temporary");assertThat(R2Settings.playbackFrom(e).finalBucket).isEqualTo("song-record-experiment-final");assertThat(R2Settings.playbackFrom(e).accessKey).isEqualTo("reader-access");}
 @Test void experimentNamesWithoutScopeAndMixedBucketPairsRemainRejected(){assertThatThrownBy(()->R2Settings.from(settings().withProperty("songrecord.deployment.storage-scope","default"))).isInstanceOf(IllegalStateException.class);for(var kind:new String[]{"temporary","final"})assertThatThrownBy(()->R2Settings.from(settings().withProperty("songrecord.storage.dev."+kind+"-bucket","song-record-staging-dev-"+kind))).isInstanceOf(IllegalStateException.class);}
 @Test void otherDatabaseAndMixedProfilesCannotBorrowExperimentScope(){for(var name:new String[]{"DB_NAME","DB_USER"})assertThatThrownBy(()->R2Settings.from(settings().withProperty(name,"song_record_validation"))).isInstanceOf(IllegalStateException.class);for(var profile:new String[]{"dev","prod","bootstrap","test","candidate-fixtures","development"}){var e=settings();e.setActiveProfiles("staging",profile);assertThatThrownBy(()->R2Settings.playbackFrom(e)).isInstanceOf(IllegalStateException.class);}}
}
